import { Group, Mesh, PlaneGeometry, Shape, ShapeGeometry, ExtrudeGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color, DoubleSide, FrontSide, Vector2 } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, step, fract, uniform, float, vec2, abs, pow, min, max } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Shape, ShapeGeometry, ExtrudeGeometry, Color, DoubleSide, FrontSide } = ctx.THREE;
  const { MeshStandardNodeMaterial, MeshBasicNodeMaterial } = THREE_webgpu;
  const { uv, vec3, mix, smoothstep, step, fract, uniform, float, vec2, abs, pow, min, max } = TSL;

  const group = new Group();
  group.name = 'gradient-cta';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelItem = items.find(i => i.role === 'cta-label') || items[0] || { text: 'BEGIN COMMISSION' };
  const captionItem = items.find(i => i.role === 'caption') || items[1] || { text: 'NO DEPOSIT REQUIRED' };

  // --- Backdrop gradient stage ---
  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    new MeshBasicNodeMaterial({ transparent: true })
  );
  backdrop.position.set(0, 0, -2.5);
  backdrop.material.colorNode = mix(
    vec3(Color('#0b0b10')),
    vec3(Color('#16161d')),
    uv().y.smoothstep(0.0, 1.0)
  );
  backdrop.material.opacityNode = float(0.95);
  group.add(backdrop);

  // --- Key, Rim, and Accent lights (node-local) ---
  const keyLight = new ctx.THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 3, 4);
  group.add(keyLight);

  const rimLight = new ctx.THREE.DirectionalLight(0xffffff, 0.7);
  rimLight.position.set(-2, 1, -3);
  group.add(rimLight);

  const ambient = new ctx.THREE.AmbientLight(0xffffff, 0.4);
  group.add(ambient);

  const accentLight = new ctx.THREE.PointLight(0xff2a38, 1.4, 8, 2);
  accentLight.position.set(-1.5, -0.5, 1.5);
  group.add(accentLight);

  // --- Button extruded geometry ---
  const W = 2.6;
  const H = 0.68;
  const R = 0.08;
  const bevelDepth = 0.03;

  const shape = new Shape();
  shape.moveTo(-W/2 + R, -H/2);
  shape.lineTo(W/2 - R, -H/2);
  shape.quadraticCurveTo(W/2, -H/2, W/2, -H/2 + R);
  shape.lineTo(W/2, H/2 - R);
  shape.quadraticCurveTo(W/2, H/2, W/2 - R, H/2);
  shape.lineTo(-W/2 + R, H/2);
  shape.quadraticCurveTo(-W/2, H/2, -W/2, H/2 - R);
  shape.lineTo(-W/2, -H/2 + R);
  shape.quadraticCurveTo(-W/2, -H/2, -W/2 + R, -H/2);

  const extrudeSettings = {
    depth: bevelDepth,
    bevelEnabled: true,
    bevelThickness: bevelDepth,
    bevelSize: bevelDepth,
    bevelSegments: 3,
    steps: 1
  };

  const buttonGeo = new ExtrudeGeometry(shape, extrudeSettings);
  buttonGeo.center();
  buttonGeo.rotateZ(0);

  const emissiveIntensity = uniform(1.6);

  const buttonMat = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.35,
    side: DoubleSide
  });

  const c0 = vec3(Color('#ff4450'));
  const c1 = vec3(Color('#ff2a38'));
  const c2 = vec3(Color('#c1121f'));

  const v = uv().y;
  const grad = mix(c0, c1, smoothstep(0.0, 0.55, v));
  const gradFinal = mix(grad, c2, smoothstep(0.55, 1.0, v));

  // hard seam at 50%
  const seam = smoothstep(0.49, 0.50, v).sub(smoothstep(0.50, 0.51, v));
  const seamColor = vec3(0.9, 0.9, 0.9).mul(seam);

  // emissive perimeter
  const edgeU = step(0.95, abs(uv().x.sub(0.5)).mul(2.0));
  const edgeV = step(0.92, abs(uv().y.sub(0.5)).mul(2.0));
  const edge = max(edgeU, edgeV);

  buttonMat.colorNode = gradFinal.add(seamColor.mul(0.3));
  buttonMat.emissiveNode = mix(vec3(0,0,0), vec3(Color('#ff2a38')), edge).mul(emissiveIntensity);
  buttonMat.roughnessNode = float(0.5);
  buttonMat.metalnessNode = float(0.35);

  const button = new Mesh(buttonGeo, buttonMat);
  button.position.set(0, 0, 0);
  group.add(button);

  // --- Contact shadow plane ---
  const contactMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  const shadowScale = uniform(0.35);
  contactMat.colorNode = vec3(0, 0, 0);
  contactMat.opacityNode = shadowScale.mul(smoothstep(0.6, 0.0, uv().sub(0.5).length()));
  const contactShadow = new Mesh(new PlaneGeometry(W * 1.2, H * 1.5), contactMat);
  contactShadow.position.set(0, -0.08, -0.05);
  contactShadow.rotation.x = -Math.PI / 2;
  group.add(contactShadow);

  // --- Text ---
  const labelOpts = { fontSize: 20, color: '#e8ecf2', align: 'center', letterSpacingPx: 1.6 };
  const labelMesh = ctx.fontAtlas.createText(String(labelItem.text), labelOpts);
  labelMesh.position.set(0, 0.01, bevelDepth + 0.001);
  group.add(labelMesh);

  const captionOpts = { fontSize: 9, color: '#e8ecf2', align: 'center', letterSpacingPx: 1.08 };
  const captionMesh = ctx.fontAtlas.createText(String(captionItem.text), captionOpts);
  captionMesh.position.set(0, -0.25 - H/2, 0);
  group.add(captionMesh);

  // --- Mount motion: weighted-settle ---
  const intro = gsap.timeline();
  intro.fromTo(button.scale, { x: 1.04, y: 1.04, z: 1.04 }, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' });
  intro.fromTo(labelMesh.position, { z: bevelDepth + 0.1 }, { z: bevelDepth + 0.001, duration: 0.9, ease: 'power4.out' }, 0);
  intro.fromTo(group.position, { y: 0.2 }, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);

  // --- Interaction handlers ---
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(button.position, { z: 0.06, duration: 0.18, ease: 'power2.out' });
  hoverTl.to(emissiveIntensity, { value: 2.2, duration: 0.18, ease: 'power2.out' }, 0);
  hoverTl.to(labelMesh.position, { z: bevelDepth + 0.06 + 0.001, duration: 0.18, ease: 'power2.out' }, 0);
  hoverTl.to(shadowScale, { value: 0.25, duration: 0.18, ease: 'power2.out' }, 0);

  const pressTl = gsap.timeline({ paused: true });
  pressTl.to(button.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'expo.in' });
  pressTl.to(shadowScale, { value: 0.5, duration: 0.12, ease: 'expo.in' }, 0);

  group.userData.handlers = {
    onPointerEnter: () => { hoverTl.play(); },
    onPointerLeave: () => { hoverTl.reverse(); },
    onPointerDown: () => { pressTl.play(); },
    onPointerUp: () => { pressTl.reverse(); },
    onClick: () => { ctx.emit('navigate', { to: 'hub-pricing' }); }
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    intro.kill();
    hoverTl.kill();
    pressTl.kill();
    buttonGeo.dispose();
    buttonMat.dispose();
    contactShadow.geometry.dispose();
    contactMat.dispose();
    backdrop.geometry.dispose();
    backdrop.material.dispose();
  };

  return group;
}
